/**
 * Confirmation Modal Component
 *
 * Generic reusable modal for confirmation scenarios (delete, warning, info).
 * Provides accessible keyboard navigation and focus management.
 */

import { Info, Warning, WarningCircle } from '@phosphor-icons/react';
import type React from 'react';
import { useEffect, useRef } from 'react';
import './ConfirmationModal.css';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/spacing.css';

export interface ConfirmationModalProps {
  isOpen: boolean;
  title: string;
  message: string | React.ReactNode;
  confirmText?: string;
  cancelText?: string;
  variant?: 'danger' | 'warning' | 'info';
  onConfirm: () => void;
  onCancel: () => void;
  isProcessing?: boolean;
}

export function ConfirmationModal({
  isOpen,
  title,
  message,
  confirmText = 'Delete',
  cancelText = 'Cancel',
  variant = 'danger',
  onConfirm,
  onCancel,
  isProcessing = false,
}: ConfirmationModalProps) {
  const modalRef = useRef<HTMLDivElement>(null);
  const cancelButtonRef = useRef<HTMLButtonElement>(null);

  // Focus cancel button when modal opens (safer default than confirm)
  useEffect(() => {
    if (isOpen && cancelButtonRef.current) {
      cancelButtonRef.current.focus();
    }
  }, [isOpen]);

  // Handle escape key
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen && !isProcessing) {
        onCancel();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
      // Prevent body scroll when modal is open
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = '';
    };
  }, [isOpen, isProcessing, onCancel]);

  // Focus trap
  useEffect(() => {
    if (!isOpen || !modalRef.current) return;

    const modal = modalRef.current;
    const focusableElements = modal.querySelectorAll<HTMLElement>(
      'button:not([disabled]), [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
    );
    const firstElement = focusableElements[0];
    const lastElement = focusableElements[focusableElements.length - 1];

    const handleTab = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;

      if (e.shiftKey) {
        if (document.activeElement === firstElement) {
          e.preventDefault();
          lastElement.focus();
        }
      } else {
        if (document.activeElement === lastElement) {
          e.preventDefault();
          firstElement.focus();
        }
      }
    };

    modal.addEventListener('keydown', handleTab);
    return () => modal.removeEventListener('keydown', handleTab);
  }, [isOpen]);

  if (!isOpen) return null;

  // Get variant-specific styling
  const variantConfig = {
    danger: {
      icon: Warning,
      iconBgColor: 'var(--color-error-subtle)',
      iconColor: 'var(--color-error)',
      confirmBgColor: 'var(--color-error)',
    },
    warning: {
      icon: WarningCircle,
      iconBgColor: 'var(--color-warning-bg)',
      iconColor: 'var(--color-warning)',
      confirmBgColor: 'var(--color-warning)',
    },
    info: {
      icon: Info,
      iconBgColor: 'var(--color-info-light)',
      iconColor: 'var(--color-info)',
      confirmBgColor: 'var(--color-primary)',
    },
  };

  const config = variantConfig[variant];
  const IconComponent = config.icon;

  return (
    <div
      className="confirmation-modal-overlay option-1 typo-1 icons-1 button-2"
      onClick={isProcessing ? undefined : onCancel}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
      aria-describedby="modal-message"
    >
      <div
        ref={modalRef}
        className="confirmation-modal-content"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header with icon */}
        <div className="confirmation-modal-header">
          <div
            className="confirmation-modal-icon-wrapper"
            style={{ backgroundColor: config.iconBgColor }}
          >
            <IconComponent
              size={24}
              weight="duotone"
              style={{ color: config.iconColor }}
              aria-hidden="true"
            />
          </div>
          <h2 id="modal-title" className="confirmation-modal-title">
            {title}
          </h2>
        </div>

        {/* Message */}
        <div id="modal-message" className="confirmation-modal-message">
          {message}
        </div>

        {/* Actions */}
        <div className="confirmation-modal-actions">
          <button
            ref={cancelButtonRef}
            className="btn btn-secondary btn-base"
            onClick={onCancel}
            disabled={isProcessing}
            type="button"
          >
            {cancelText}
          </button>
          <button
            className="btn btn-base"
            onClick={onConfirm}
            disabled={isProcessing}
            style={{
              backgroundColor: config.confirmBgColor,
              color: 'white',
              border: 'none',
            }}
            type="button"
          >
            {isProcessing ? 'Processing...' : confirmText}
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Confirm Delete Modal Component
 *
 * Reusable modal for confirming delete operations.
 * Used instead of window.confirm() which doesn't work in Tauri.
 */

import { Trash, Warning } from '@phosphor-icons/react';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/spacing.css';

interface ConfirmDeleteModalProps {
  title: string;
  message: string;
  itemName: string;
  onConfirm: () => void;
  onCancel: () => void;
  isDeleting?: boolean;
}

export function ConfirmDeleteModal({
  title,
  message,
  itemName,
  onConfirm,
  onCancel,
  isDeleting = false,
}: ConfirmDeleteModalProps) {
  return (
    <div
      className="option-1 typo-1 icons-1 button-2"
      style={{
        position: 'fixed',
        inset: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
        zIndex: 1000,
      }}
      onClick={onCancel}
    >
      <div
        style={{
          backgroundColor: 'var(--color-surface)',
          borderRadius: '8px',
          padding: 'var(--spacing-6)',
          maxWidth: '400px',
          width: '90%',
          boxShadow: 'var(--shadow-lg)',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header with warning icon */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--spacing-3)',
            marginBottom: 'var(--spacing-4)',
          }}
        >
          <div
            style={{
              width: '40px',
              height: '40px',
              borderRadius: '50%',
              backgroundColor: 'var(--color-error-subtle)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              flexShrink: 0,
            }}
          >
            <Warning size={24} weight="duotone" style={{ color: 'var(--color-error)' }} />
          </div>
          <h2
            style={{
              fontFamily: 'var(--typography-heading-font)',
              fontSize: 'var(--typography-h3-size)',
              fontWeight: 'var(--typography-h3-weight)',
              color: 'var(--color-text-primary)',
              margin: 0,
            }}
          >
            {title}
          </h2>
        </div>

        {/* Message */}
        <p
          style={{
            fontFamily: 'var(--typography-body-font)',
            fontSize: 'var(--font-size-base)',
            color: 'var(--color-text-secondary)',
            marginBottom: 'var(--spacing-3)',
            lineHeight: 'var(--typography-body-line-height)',
          }}
        >
          {message}
        </p>

        {/* Item name highlight */}
        <div
          style={{
            padding: 'var(--spacing-3)',
            backgroundColor: 'var(--color-background)',
            borderRadius: '4px',
            marginBottom: 'var(--spacing-6)',
          }}
        >
          <span
            style={{
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-base)',
              fontWeight: 'var(--font-weight-semibold)',
              color: 'var(--color-text-primary)',
            }}
          >
            {itemName}
          </span>
        </div>

        {/* Actions */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'flex-end',
            gap: 'var(--spacing-3)',
          }}
        >
          <button className="btn btn-secondary btn-base" onClick={onCancel} disabled={isDeleting}>
            Cancel
          </button>
          <button
            className="btn btn-base"
            onClick={onConfirm}
            disabled={isDeleting}
            style={{
              backgroundColor: 'var(--color-error)',
              color: 'white',
              border: 'none',
            }}
          >
            <Trash className="icon icon-base" weight="duotone" />
            {isDeleting ? 'Deleting...' : 'Delete'}
          </button>
        </div>
      </div>
    </div>
  );
}

import type React from 'react';
import { useEffect, useRef, useState } from 'react';
import './CreateUniverseModal.css';

interface CreateUniverseModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (name: string) => void;
}

export const CreateUniverseModal: React.FC<CreateUniverseModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
}) => {
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  // Focus input when modal opens
  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  // Handle escape key
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };

    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, [isOpen, onClose]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validation
    if (!name.trim()) {
      setError('Universe name is required');
      return;
    }

    if (name.trim().length < 2) {
      setError('Universe name must be at least 2 characters');
      return;
    }

    // Submit
    onSubmit(name.trim());
    setName('');
    setError('');
  };

  const handleClose = () => {
    setName('');
    setError('');
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={handleClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2 className="modal-title">Create New Universe</h2>
          <button className="modal-close" onClick={handleClose} aria-label="Close modal">
            ×
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="universe-name" className="form-label">
              Universe Name
            </label>
            <input
              ref={inputRef}
              id="universe-name"
              type="text"
              className={`form-input ${error ? 'form-input--error' : ''}`}
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                setError('');
              }}
              placeholder="Enter universe name"
              aria-invalid={!!error}
              aria-describedby={error ? 'name-error' : undefined}
            />
            {error && (
              <p id="name-error" className="form-error">
                {error}
              </p>
            )}
          </div>

          <div className="modal-actions">
            <button type="button" className="btn btn-secondary btn-base" onClick={handleClose}>
              Cancel
            </button>
            <button type="submit" className="btn btn-primary btn-base">
              Create Universe
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

/**
 * Create Story Modal
 *
 * Modal component for creating a new story with form validation and error handling.
 */

import { X } from '@phosphor-icons/react';
import { type FormEvent, useEffect, useState } from 'react';
import { useContainersStore } from '@/features/containers/stores/useContainersStore';
import { useStoriesStore } from '@/features/stories/stores/useStoriesStore';
import { useUniverseStore } from '@/features/universe/stores/useUniverseStore';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import type { StoryType } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';

interface CreateStoryModalProps {
  onClose: () => void;
  containerId?: string; // If provided, story will be created in this container
}

// Content-only story types (no container types like 'novel', 'series')
const storyTypeOptions: { value: StoryType; label: string }[] = [
  { value: 'chapter', label: 'Chapter' },
  { value: 'scene', label: 'Scene' },
  { value: 'short-story', label: 'Short Story' },
  { value: 'episode', label: 'Episode' },
  { value: 'poem', label: 'Poem' },
  { value: 'outline', label: 'Outline' },
  { value: 'treatment', label: 'Treatment' },
  { value: 'screenplay', label: 'Screenplay' },
];

export function CreateStoryModal({ onClose, containerId }: CreateStoryModalProps) {
  const navigate = useNavigationStore((state) => state.navigate);
  const currentUniverse = useUniverseStore((state) => state.currentUniverse);
  const { createStory } = useStoriesStore();
  const { containers } = useContainersStore();

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    storyType: 'chapter' as StoryType,
    containerId: containerId || '', // Empty string means standalone
    targetWordCount: '',
    tags: '',
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Load containers on mount if universe is selected
  useEffect(() => {
    if (currentUniverse && containers.length === 0) {
      useContainersStore.getState().loadContainers(currentUniverse.id);
    }
  }, [currentUniverse, containers.length]);

  // Show all containers - backend will validate when creating story
  // A container can hold stories if it doesn't have child containers
  // Backend has leaf protection to prevent adding stories to containers with children
  const availableContainers = containers;

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    // Validate
    const newErrors: Record<string, string> = {};
    if (!formData.title.trim()) {
      newErrors.title = 'Title is required';
    }
    if (!formData.description.trim()) {
      newErrors.description = 'Description is required';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    if (!currentUniverse) {
      setErrors({ general: 'No universe selected' });
      return;
    }

    // Submit
    setIsSubmitting(true);
    setErrors({});

    try {
      const story = await createStory({
        universeId: currentUniverse.id,
        title: formData.title.trim(),
        description: formData.description.trim(),
        storyType: formData.storyType,
        // Note: content is managed via DBV (versions/snapshots), not CreateStoryInput
        notes: null,
        outline: null,
        targetWordCount: formData.targetWordCount ? parseInt(formData.targetWordCount, 10) : null,
        tags: formData.tags
          ? formData.tags
              .split(',')
              .map((t) => t.trim())
              .filter(Boolean)
          : null,
        color: null,
        seriesName: null,
        containerId: formData.containerId || null, // null = standalone story
        variationType: null,
        parentVariationId: null,
      });

      // Invalidate container children cache if story was added to container
      if (formData.containerId) {
        useContainersStore.getState().invalidateChildren(formData.containerId);
      }

      // Navigate to story editor
      navigate({ screen: 'story-editor', storyId: story.id });
      onClose();
    } catch (error) {
      console.error('Failed to create story:', error);
      setErrors({
        general: error instanceof Error ? error.message : 'Failed to create story',
      });
      setIsSubmitting(false);
    }
  };

  return (
    <div
      className="option-1 typo-1 icons-1 button-2 input-5"
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 1000,
        padding: 'var(--spacing-4)',
      }}
      onClick={onClose}
    >
      <div
        style={{
          backgroundColor: 'var(--color-surface)',
          borderRadius: '8px',
          maxWidth: '600px',
          width: '100%',
          maxHeight: '90vh',
          overflow: 'auto',
          boxShadow: 'var(--shadow-xl)',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: 'var(--spacing-6)',
            borderBottom: '1px solid var(--color-border)',
          }}
        >
          <div>
            <h2
              style={{
                fontFamily: 'var(--typography-heading-font)',
                fontSize: 'var(--typography-h3-size)',
                fontWeight: 'var(--typography-h3-weight)',
                color: 'var(--color-text-primary)',
                margin: 0,
              }}
            >
              Create New Story
            </h2>
          </div>
          <button
            className="btn btn-ghost btn-sm"
            onClick={onClose}
            aria-label="Close modal"
            style={{ padding: 'var(--spacing-1)' }}
          >
            <X className="icon icon-base" weight="duotone" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit}>
          <div
            style={{
              padding: 'var(--spacing-6)',
              display: 'flex',
              flexDirection: 'column',
              gap: 'var(--spacing-5)',
            }}
          >
            {/* General Error */}
            {errors.general && (
              <div
                style={{
                  padding: 'var(--spacing-3)',
                  backgroundColor: 'var(--color-error-subtle)',
                  color: 'var(--color-error)',
                  borderRadius: '4px',
                  fontFamily: 'var(--typography-body-font)',
                  fontSize: 'var(--font-size-sm)',
                }}
              >
                {errors.general}
              </div>
            )}

            {/* Container Selection (optional) */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="story-container">
                Container
              </label>
              <div className="input-wrapper">
                <select
                  id="story-container"
                  className="input-field input-base"
                  value={formData.containerId}
                  onChange={(e) => setFormData({ ...formData, containerId: e.target.value })}
                  disabled={!!containerId} // Disable if container was pre-selected
                  style={{
                    backgroundColor: 'var(--color-surface)',
                    border: '1px solid var(--color-border)',
                    borderRadius: '4px',
                    padding: 'var(--spacing-2) var(--spacing-3)',
                    fontFamily: 'var(--typography-body-font)',
                    fontSize: 'var(--font-size-base)',
                    color: 'var(--color-text-primary)',
                  }}
                >
                  <option value="">Standalone (no container)</option>
                  {availableContainers.map((container) => (
                    <option key={container.id} value={container.id}>
                      {container.title}
                    </option>
                  ))}
                </select>
              </div>
              <div className="input-helper">Optional: Add story to a container</div>
            </div>

            {/* Story Type */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="story-type">
                Story Type
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <select
                  id="story-type"
                  className="input-field input-base"
                  value={formData.storyType}
                  onChange={(e) =>
                    setFormData({ ...formData, storyType: e.target.value as StoryType })
                  }
                  style={{
                    backgroundColor: 'var(--color-surface)',
                    border: '1px solid var(--color-border)',
                    borderRadius: '4px',
                    padding: 'var(--spacing-2) var(--spacing-3)',
                    fontFamily: 'var(--typography-body-font)',
                    fontSize: 'var(--font-size-base)',
                    color: 'var(--color-text-primary)',
                  }}
                >
                  {storyTypeOptions.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Title */}
            <div className={`input-group input-5 ${errors.title ? 'has-error' : ''}`}>
              <label className="input-label" htmlFor="story-title">
                Title
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <input
                  id="story-title"
                  type="text"
                  className="input-field input-base"
                  placeholder="Enter story title"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  required
                />
              </div>
              {errors.title && <div className="input-helper">{errors.title}</div>}
            </div>

            {/* Description */}
            <div className={`input-group input-5 ${errors.description ? 'has-error' : ''}`}>
              <label className="input-label" htmlFor="story-description">
                Description
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <textarea
                  id="story-description"
                  className="input-field input-base"
                  placeholder="Brief description of your story"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  rows={3}
                  required
                  style={{
                    resize: 'vertical',
                    minHeight: '80px',
                  }}
                />
              </div>
              {errors.description && <div className="input-helper">{errors.description}</div>}
            </div>

            {/* Target Word Count */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="story-word-count">
                Target Word Count
              </label>
              <div className="input-wrapper">
                <input
                  id="story-word-count"
                  type="number"
                  className="input-field input-base"
                  placeholder="e.g., 80000"
                  value={formData.targetWordCount}
                  onChange={(e) => setFormData({ ...formData, targetWordCount: e.target.value })}
                  min="0"
                />
              </div>
              <div className="input-helper">Optional goal for story length</div>
            </div>

            {/* Tags */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="story-tags">
                Tags
              </label>
              <div className="input-wrapper">
                <input
                  id="story-tags"
                  type="text"
                  className="input-field input-base"
                  placeholder="fantasy, adventure, epic"
                  value={formData.tags}
                  onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
                />
              </div>
              <div className="input-helper">Comma-separated tags</div>
            </div>
          </div>

          {/* Footer */}
          <div
            style={{
              display: 'flex',
              justifyContent: 'flex-end',
              gap: 'var(--spacing-3)',
              padding: 'var(--spacing-6)',
              borderTop: '1px solid var(--color-border)',
              backgroundColor: 'var(--color-background)',
            }}
          >
            <button
              type="button"
              className="btn btn-ghost btn-base"
              onClick={onClose}
              disabled={isSubmitting}
            >
              Cancel
            </button>
            <button type="submit" className="btn btn-primary btn-base" disabled={isSubmitting}>
              {isSubmitting ? 'Creating...' : 'Create Story'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * Create Container Modal
 *
 * Modal component for creating a new container (Novel, Series, Collection).
 */

import { X } from '@phosphor-icons/react';
import { type FormEvent, useState } from 'react';
import { useContainersStore } from '@/features/containers/stores/useContainersStore';
import { useUniverseStore } from '@/features/universe/stores/useUniverseStore';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';

interface CreateContainerModalProps {
  onClose: () => void;
  parentContainer?: {
    id: string;
    title: string;
  };
}

type ContainerType = 'novel' | 'series' | 'collection';

const containerTypeOptions: { value: ContainerType; label: string }[] = [
  { value: 'novel', label: 'Novel' },
  { value: 'series', label: 'Series' },
  { value: 'collection', label: 'Collection' },
];

export function CreateContainerModal({ onClose, parentContainer }: CreateContainerModalProps) {
  const navigate = useNavigationStore((state) => state.navigate);
  const currentUniverse = useUniverseStore((state) => state.currentUniverse);
  const { createContainer } = useContainersStore();

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    containerType: 'novel' as ContainerType,
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    // Validate
    const newErrors: Record<string, string> = {};
    if (!formData.title.trim()) {
      newErrors.title = 'Title is required';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    if (!currentUniverse) {
      setErrors({ general: 'No universe selected' });
      return;
    }

    // Submit
    setIsSubmitting(true);
    setErrors({});

    try {
      const container = await createContainer({
        universeId: currentUniverse.id,
        parentContainerId: parentContainer?.id || null,
        containerType: formData.containerType,
        title: formData.title.trim(),
        description: formData.description.trim() || null,
        order: null, // Backend will auto-assign order
      });

      // Navigate to container view
      navigate({ screen: 'container-view', containerId: container.id });
      onClose();
    } catch (error) {
      console.error('Failed to create container:', error);
      setErrors({
        general: error instanceof Error ? error.message : 'Failed to create container',
      });
      setIsSubmitting(false);
    }
  };

  return (
    <div
      className="option-1 typo-1 icons-1 button-2 input-5"
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 1000,
        padding: 'var(--spacing-4)',
      }}
      onClick={onClose}
    >
      <div
        style={{
          backgroundColor: 'var(--color-surface)',
          borderRadius: '8px',
          maxWidth: '600px',
          width: '100%',
          maxHeight: '90vh',
          overflow: 'auto',
          boxShadow: 'var(--shadow-xl)',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: 'var(--spacing-6)',
            borderBottom: '1px solid var(--color-border)',
          }}
        >
          <div>
            <h2
              style={{
                fontFamily: 'var(--typography-heading-font)',
                fontSize: 'var(--typography-h3-size)',
                fontWeight: 'var(--typography-h3-weight)',
                color: 'var(--color-text-primary)',
                margin: 0,
              }}
            >
              Create New Container
            </h2>
            {parentContainer && (
              <p
                style={{
                  fontFamily: 'var(--typography-body-font)',
                  fontSize: 'var(--font-size-sm)',
                  color: 'var(--color-text-secondary)',
                  margin: '4px 0 0 0',
                }}
              >
                Adding to: {parentContainer.title}
              </p>
            )}
          </div>
          <button
            className="btn btn-ghost btn-sm"
            onClick={onClose}
            aria-label="Close modal"
            style={{ padding: 'var(--spacing-1)' }}
          >
            <X className="icon icon-base" weight="duotone" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit}>
          <div
            style={{
              padding: 'var(--spacing-6)',
              display: 'flex',
              flexDirection: 'column',
              gap: 'var(--spacing-5)',
            }}
          >
            {/* General Error */}
            {errors.general && (
              <div
                style={{
                  padding: 'var(--spacing-3)',
                  backgroundColor: 'var(--color-error-subtle)',
                  color: 'var(--color-error)',
                  borderRadius: '4px',
                  fontFamily: 'var(--typography-body-font)',
                  fontSize: 'var(--font-size-sm)',
                }}
              >
                {errors.general}
              </div>
            )}

            {/* Container Type */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="container-type">
                Container Type
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <select
                  id="container-type"
                  className="input-field input-base"
                  value={formData.containerType}
                  onChange={(e) =>
                    setFormData({ ...formData, containerType: e.target.value as ContainerType })
                  }
                  style={{
                    backgroundColor: 'var(--color-surface)',
                    border: '1px solid var(--color-border)',
                    borderRadius: '4px',
                    padding: 'var(--spacing-2) var(--spacing-3)',
                    fontFamily: 'var(--typography-body-font)',
                    fontSize: 'var(--font-size-base)',
                    color: 'var(--color-text-primary)',
                  }}
                >
                  {containerTypeOptions.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Title */}
            <div className={`input-group input-5 ${errors.title ? 'has-error' : ''}`}>
              <label className="input-label" htmlFor="container-title">
                Title
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <input
                  id="container-title"
                  type="text"
                  className="input-field input-base"
                  placeholder="Enter container title"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  required
                />
              </div>
              {errors.title && <div className="input-helper">{errors.title}</div>}
            </div>

            {/* Description */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="container-description">
                Description
              </label>
              <div className="input-wrapper">
                <textarea
                  id="container-description"
                  className="input-field input-base"
                  placeholder="Brief description of this container"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  rows={3}
                  style={{
                    resize: 'vertical',
                    minHeight: '80px',
                  }}
                />
              </div>
              <div className="input-helper">Optional description</div>
            </div>
          </div>

          {/* Footer */}
          <div
            style={{
              display: 'flex',
              justifyContent: 'flex-end',
              gap: 'var(--spacing-3)',
              padding: 'var(--spacing-6)',
              borderTop: '1px solid var(--color-border)',
              backgroundColor: 'var(--color-background)',
            }}
          >
            <button
              type="button"
              className="btn btn-ghost btn-base"
              onClick={onClose}
              disabled={isSubmitting}
            >
              Cancel
            </button>
            <button type="submit" className="btn btn-primary btn-base" disabled={isSubmitting}>
              {isSubmitting ? 'Creating...' : 'Create Container'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * Create Element Modal
 *
 * Modal component for creating a new universe element with template selection.
 * Loads suggested attributes from element-templates.json based on selected template.
 */

import { X } from '@phosphor-icons/react';
import { type FormEvent, useState } from 'react';
import { useElementsStore } from '@/features/elements/stores/useElementsStore';
import { useUniverseStore } from '@/features/universe/stores/useUniverseStore';
import elementTemplatesData from '@/shared/config/element-templates.json';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import type { ElementType } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';

interface CreateElementModalProps {
  onClose: () => void;
}

interface TemplateData {
  name: string;
  description: string;
  icon: string;
  suggestedAttributes: Array<{
    key: string;
    label: string;
    placeholder: string;
    description: string;
  }>;
}

type TemplateKey =
  | 'character'
  | 'location'
  | 'vehicle'
  | 'item'
  | 'organization'
  | 'creature'
  | 'event'
  | 'concept';

const templates: Record<TemplateKey, TemplateData> = elementTemplatesData.templates as any;

export function CreateElementModal({ onClose }: CreateElementModalProps) {
  const navigate = useNavigationStore((state) => state.navigate);
  const currentUniverse = useUniverseStore((state) => state.currentUniverse);
  const { createElement } = useElementsStore();

  const [step, setStep] = useState<'select-template' | 'fill-form'>('select-template');
  const [selectedTemplate, setSelectedTemplate] = useState<TemplateKey | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    details: '',
    tags: '',
    color: '',
  });

  const [attributes, setAttributes] = useState<Record<string, string>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleTemplateSelect = (templateKey: TemplateKey) => {
    setSelectedTemplate(templateKey);
    setStep('fill-form');
  };

  const handleAttributeChange = (key: string, value: string) => {
    setAttributes({ ...attributes, [key]: value });
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    // Validate
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }
    if (!formData.description.trim()) {
      newErrors.description = 'Description is required';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    if (!currentUniverse) {
      setErrors({ general: 'No universe selected' });
      return;
    }

    if (!selectedTemplate) {
      setErrors({ general: 'No template selected' });
      return;
    }

    // Submit
    setIsSubmitting(true);
    setErrors({});

    try {
      // Filter out empty attributes
      const filteredAttributes = Object.fromEntries(
        Object.entries(attributes).filter(([_, value]) => value.trim() !== ''),
      );

      const element = await createElement({
        universeId: currentUniverse.id,
        name: formData.name.trim(),
        description: formData.description.trim(),
        elementType: selectedTemplate as ElementType,
        customTypeName: null,
        details: formData.details.trim() || null,
        attributes: Object.keys(filteredAttributes).length > 0 ? filteredAttributes : null,
        imageUrl: null,
        tags: formData.tags
          ? formData.tags
              .split(',')
              .map((t) => t.trim())
              .filter(Boolean)
          : null,
        relationships: null,
        color: formData.color.trim() || null,
        icon: null, // Icons are now determined by element type (Phosphor icons)
      });

      // Navigate to element detail
      navigate({ screen: 'element-detail', elementId: element.id });
      onClose();
    } catch (error) {
      console.error('Failed to create element:', error);
      setErrors({
        general: error instanceof Error ? error.message : 'Failed to create element',
      });
      setIsSubmitting(false);
    }
  };

  const handleBack = () => {
    setStep('select-template');
    setSelectedTemplate(null);
    setAttributes({});
  };

  const templateData = selectedTemplate ? templates[selectedTemplate] : null;

  return (
    <div
      className="option-1 typo-1 icons-1 button-2 input-5"
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 1000,
        padding: 'var(--spacing-4)',
      }}
      onClick={onClose}
    >
      <div
        style={{
          backgroundColor: 'var(--color-surface)',
          borderRadius: '8px',
          maxWidth: '800px',
          width: '100%',
          maxHeight: '90vh',
          overflow: 'auto',
          boxShadow: 'var(--shadow-xl)',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: 'var(--spacing-6)',
            borderBottom: '1px solid var(--color-border)',
          }}
        >
          <h2
            style={{
              fontFamily: 'var(--typography-heading-font)',
              fontSize: 'var(--typography-h3-size)',
              fontWeight: 'var(--typography-h3-weight)',
              color: 'var(--color-text-primary)',
              margin: 0,
            }}
          >
            {step === 'select-template' ? 'Choose Element Type' : `Create ${templateData?.name}`}
          </h2>
          <button
            className="btn btn-ghost btn-sm"
            onClick={onClose}
            aria-label="Close modal"
            style={{ padding: 'var(--spacing-1)' }}
          >
            <X className="icon icon-base" weight="duotone" />
          </button>
        </div>

        {/* Template Selection */}
        {step === 'select-template' && (
          <div
            style={{
              padding: 'var(--spacing-6)',
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))',
              gap: 'var(--spacing-4)',
            }}
          >
            {(Object.keys(templates) as TemplateKey[]).map((key) => {
              const template = templates[key];
              return (
                <button
                  key={key}
                  className="btn btn-outline btn-base"
                  onClick={() => handleTemplateSelect(key)}
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'flex-start',
                    gap: 'var(--spacing-2)',
                    padding: 'var(--spacing-4)',
                    height: 'auto',
                    textAlign: 'center',
                    whiteSpace: 'normal',
                  }}
                >
                  <span style={{ fontSize: '32px', flexShrink: 0 }}>{template.icon}</span>
                  <span
                    style={{
                      fontFamily: 'var(--typography-heading-font)',
                      fontWeight: 'var(--font-weight-semibold)',
                      flexShrink: 0,
                    }}
                  >
                    {template.name}
                  </span>
                  <span
                    style={{
                      fontSize: 'var(--font-size-xs)',
                      color: 'var(--color-text-secondary)',
                      lineHeight: '1.4',
                      whiteSpace: 'normal',
                      wordWrap: 'break-word',
                    }}
                  >
                    {template.description}
                  </span>
                </button>
              );
            })}
          </div>
        )}

        {/* Form */}
        {step === 'fill-form' && templateData && (
          <form onSubmit={handleSubmit}>
            <div
              style={{
                padding: 'var(--spacing-6)',
                display: 'flex',
                flexDirection: 'column',
                gap: 'var(--spacing-5)',
              }}
            >
              {/* General Error */}
              {errors.general && (
                <div
                  style={{
                    padding: 'var(--spacing-3)',
                    backgroundColor: 'var(--color-error-subtle)',
                    color: 'var(--color-error)',
                    borderRadius: '4px',
                    fontFamily: 'var(--typography-body-font)',
                    fontSize: 'var(--font-size-sm)',
                  }}
                >
                  {errors.general}
                </div>
              )}

              {/* Name (Required) */}
              <div className={`input-group input-5 ${errors.name ? 'has-error' : ''}`}>
                <label className="input-label" htmlFor="element-name">
                  Name
                  <span className="required">*</span>
                </label>
                <div className="input-wrapper">
                  <input
                    id="element-name"
                    type="text"
                    className="input-field input-base"
                    placeholder={`e.g., ${templateData.name === 'Character' ? 'John Smith' : templateData.name === 'Location' ? 'Ancient Forest' : 'Example Name'}`}
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    required
                  />
                </div>
                {errors.name && <div className="input-helper">{errors.name}</div>}
              </div>

              {/* Description (Required) */}
              <div className={`input-group input-5 ${errors.description ? 'has-error' : ''}`}>
                <label className="input-label" htmlFor="element-description">
                  Description
                  <span className="required">*</span>
                </label>
                <div className="input-wrapper">
                  <textarea
                    id="element-description"
                    className="input-field input-base"
                    placeholder="Brief one-line description"
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    rows={2}
                    required
                    style={{
                      resize: 'vertical',
                      minHeight: '60px',
                    }}
                  />
                </div>
                {errors.description && <div className="input-helper">{errors.description}</div>}
              </div>

              {/* Details (Optional) */}
              <div className="input-group input-5">
                <label className="input-label" htmlFor="element-details">
                  Details
                </label>
                <div className="input-wrapper">
                  <textarea
                    id="element-details"
                    className="input-field input-base"
                    placeholder="Longer-form text content and notes"
                    value={formData.details}
                    onChange={(e) => setFormData({ ...formData, details: e.target.value })}
                    rows={4}
                    style={{
                      resize: 'vertical',
                      minHeight: '100px',
                    }}
                  />
                </div>
                <div className="input-helper">Optional detailed information</div>
              </div>

              {/* Suggested Attributes */}
              {templateData.suggestedAttributes.length > 0 && (
                <>
                  <div
                    style={{
                      borderTop: '1px solid var(--color-border)',
                      paddingTop: 'var(--spacing-4)',
                    }}
                  >
                    <h3
                      style={{
                        fontFamily: 'var(--typography-heading-font)',
                        fontSize: 'var(--font-size-lg)',
                        fontWeight: 'var(--font-weight-semibold)',
                        color: 'var(--color-text-primary)',
                        margin: 0,
                        marginBottom: 'var(--spacing-3)',
                      }}
                    >
                      Suggested Attributes (Optional)
                    </h3>
                    <p
                      style={{
                        fontFamily: 'var(--typography-body-font)',
                        fontSize: 'var(--font-size-sm)',
                        color: 'var(--color-text-secondary)',
                        margin: 0,
                        marginBottom: 'var(--spacing-4)',
                      }}
                    >
                      These attributes are suggestions based on the {templateData.name} template.
                      You can fill in any that are relevant or skip them all.
                    </p>
                  </div>

                  <div
                    style={{
                      display: 'grid',
                      gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
                      gap: 'var(--spacing-4)',
                    }}
                  >
                    {templateData.suggestedAttributes.map((attr) => (
                      <div key={attr.key} className="input-group input-5">
                        <label className="input-label" htmlFor={`attr-${attr.key}`}>
                          {attr.label}
                        </label>
                        <div className="input-wrapper">
                          <input
                            id={`attr-${attr.key}`}
                            type="text"
                            className="input-field input-base"
                            placeholder={attr.placeholder}
                            value={attributes[attr.key] || ''}
                            onChange={(e) => handleAttributeChange(attr.key, e.target.value)}
                          />
                        </div>
                        {attr.description && <div className="input-helper">{attr.description}</div>}
                      </div>
                    ))}
                  </div>
                </>
              )}

              {/* Additional Options */}
              <div
                style={{
                  borderTop: '1px solid var(--color-border)',
                  paddingTop: 'var(--spacing-4)',
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
                  gap: 'var(--spacing-4)',
                }}
              >
                {/* Tags */}
                <div className="input-group input-5">
                  <label className="input-label" htmlFor="element-tags">
                    Tags
                  </label>
                  <div className="input-wrapper">
                    <input
                      id="element-tags"
                      type="text"
                      className="input-field input-base"
                      placeholder="hero, magic, warrior"
                      value={formData.tags}
                      onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
                    />
                  </div>
                  <div className="input-helper">Comma-separated tags</div>
                </div>

                {/* Color */}
                <div className="input-group input-5">
                  <label className="input-label" htmlFor="element-color">
                    Color
                  </label>
                  <div className="input-wrapper">
                    <input
                      id="element-color"
                      type="text"
                      className="input-field input-base"
                      placeholder="#4F46E5"
                      value={formData.color}
                      onChange={(e) => setFormData({ ...formData, color: e.target.value })}
                    />
                  </div>
                  <div className="input-helper">Hex color code</div>
                </div>
              </div>
            </div>

            {/* Footer */}
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                gap: 'var(--spacing-3)',
                padding: 'var(--spacing-6)',
                borderTop: '1px solid var(--color-border)',
                backgroundColor: 'var(--color-background)',
              }}
            >
              <button
                type="button"
                className="btn btn-ghost btn-base"
                onClick={handleBack}
                disabled={isSubmitting}
              >
                Back
              </button>
              <div style={{ display: 'flex', gap: 'var(--spacing-3)' }}>
                <button
                  type="button"
                  className="btn btn-ghost btn-base"
                  onClick={onClose}
                  disabled={isSubmitting}
                >
                  Cancel
                </button>
                <button type="submit" className="btn btn-primary btn-base" disabled={isSubmitting}>
                  {isSubmitting ? 'Creating...' : 'Create Element'}
                </button>
              </div>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}

/**
 * Edit Element Modal
 *
 * Modal component for editing an existing universe element.
 * Pre-populates form with current element data and supports partial updates.
 */

import { X } from '@phosphor-icons/react';
import { type FormEvent, useState } from 'react';
import { useElementsStore } from '@/features/elements/stores/useElementsStore';
import elementTemplatesData from '@/shared/config/element-templates.json';
import type { Element, UpdateElementInput } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';

interface EditElementModalProps {
  element: Element;
  onClose: () => void;
  onSuccess: (updatedElement: Element) => void;
}

interface TemplateData {
  name: string;
  description: string;
  icon: string;
  suggestedAttributes: Array<{
    key: string;
    label: string;
    placeholder: string;
    description: string;
  }>;
}

type TemplateKey =
  | 'character'
  | 'location'
  | 'vehicle'
  | 'item'
  | 'organization'
  | 'creature'
  | 'event'
  | 'concept';

const templates: Record<TemplateKey, TemplateData> = elementTemplatesData.templates as any;

export function EditElementModal({ element, onClose, onSuccess }: EditElementModalProps) {
  const { updateElement } = useElementsStore();

  const [formData, setFormData] = useState({
    name: element.name,
    description: element.description,
    details: element.details || '',
    tags: element.tags?.join(', ') || '',
    color: element.color || '',
  });

  const [attributes, setAttributes] = useState<Record<string, string>>(() => {
    // Convert element.attributes to a Record<string, string>, filtering out undefined values
    const attrs: Record<string, string> = {};
    if (element.attributes) {
      for (const [key, value] of Object.entries(element.attributes)) {
        if (value !== undefined) {
          attrs[key] = value;
        }
      }
    }
    return attrs;
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Get template data for the element's type
  const templateData =
    element.elementType in templates ? templates[element.elementType as TemplateKey] : null;

  const handleAttributeChange = (key: string, value: string) => {
    setAttributes({ ...attributes, [key]: value });
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    // Validate
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }
    if (!formData.description.trim()) {
      newErrors.description = 'Description is required';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    // Submit
    setIsSubmitting(true);
    setErrors({});

    try {
      // Filter out empty attributes
      const filteredAttributes = Object.fromEntries(
        Object.entries(attributes).filter(([_, value]) => value.trim() !== ''),
      );

      // Build update input - only include changed fields
      const input: UpdateElementInput = {
        name: formData.name.trim() !== element.name ? formData.name.trim() : null,
        description:
          formData.description.trim() !== element.description ? formData.description.trim() : null,
        elementType: null, // Can't change element type in edit
        customTypeName: null,
        details:
          formData.details.trim() !== (element.details || '')
            ? formData.details.trim() || null
            : null,
        attributes:
          JSON.stringify(filteredAttributes) !== JSON.stringify(element.attributes || {})
            ? Object.keys(filteredAttributes).length > 0
              ? filteredAttributes
              : {}
            : null,
        imageUrl: null,
        tags:
          formData.tags !== (element.tags?.join(', ') || '')
            ? formData.tags
              ? formData.tags
                  .split(',')
                  .map((t) => t.trim())
                  .filter(Boolean)
              : []
            : null,
        relationships: null, // Keep existing relationships
        relatedStoryIds: null,
        color:
          formData.color.trim() !== (element.color || '') ? formData.color.trim() || null : null,
        icon: null, // Icons are now determined by element type (Phosphor icons)
        favorite: null, // Keep existing favorite status
        order: null,
      };

      // Check if anything actually changed
      const hasChanges = Object.values(input).some((v) => v !== null);
      if (!hasChanges) {
        // Nothing changed, just close
        onClose();
        return;
      }

      const updated = await updateElement(element.id, input);
      onSuccess(updated);
      onClose();
    } catch (error) {
      console.error('Failed to update element:', error);
      setErrors({
        general: error instanceof Error ? error.message : 'Failed to update element',
      });
      setIsSubmitting(false);
    }
  };

  return (
    <div
      className="option-1 typo-1 icons-1 button-2 input-5"
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 1000,
        padding: 'var(--spacing-4)',
      }}
      onClick={onClose}
    >
      <div
        style={{
          backgroundColor: 'var(--color-surface)',
          borderRadius: '8px',
          maxWidth: '800px',
          width: '100%',
          maxHeight: '90vh',
          overflow: 'auto',
          boxShadow: 'var(--shadow-xl)',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: 'var(--spacing-6)',
            borderBottom: '1px solid var(--color-border)',
          }}
        >
          <h2
            style={{
              fontFamily: 'var(--typography-heading-font)',
              fontSize: 'var(--typography-h3-size)',
              fontWeight: 'var(--typography-h3-weight)',
              color: 'var(--color-text-primary)',
              margin: 0,
            }}
          >
            Edit {templateData?.name || 'Element'}
          </h2>
          <button
            className="btn btn-ghost btn-sm"
            onClick={onClose}
            aria-label="Close modal"
            style={{ padding: 'var(--spacing-1)' }}
          >
            <X className="icon icon-base" weight="duotone" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit}>
          <div
            style={{
              padding: 'var(--spacing-6)',
              display: 'flex',
              flexDirection: 'column',
              gap: 'var(--spacing-5)',
            }}
          >
            {/* General Error */}
            {errors.general && (
              <div
                style={{
                  padding: 'var(--spacing-3)',
                  backgroundColor: 'var(--color-error-subtle)',
                  color: 'var(--color-error)',
                  borderRadius: '4px',
                  fontFamily: 'var(--typography-body-font)',
                  fontSize: 'var(--font-size-sm)',
                }}
              >
                {errors.general}
              </div>
            )}

            {/* Name (Required) */}
            <div className={`input-group input-5 ${errors.name ? 'has-error' : ''}`}>
              <label className="input-label" htmlFor="element-name">
                Name
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <input
                  id="element-name"
                  type="text"
                  className="input-field input-base"
                  placeholder="Element name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                />
              </div>
              {errors.name && <div className="input-helper">{errors.name}</div>}
            </div>

            {/* Description (Required) */}
            <div className={`input-group input-5 ${errors.description ? 'has-error' : ''}`}>
              <label className="input-label" htmlFor="element-description">
                Description
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <textarea
                  id="element-description"
                  className="input-field input-base"
                  placeholder="Brief one-line description"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  rows={2}
                  required
                  style={{
                    resize: 'vertical',
                    minHeight: '60px',
                  }}
                />
              </div>
              {errors.description && <div className="input-helper">{errors.description}</div>}
            </div>

            {/* Details (Optional) */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="element-details">
                Details
              </label>
              <div className="input-wrapper">
                <textarea
                  id="element-details"
                  className="input-field input-base"
                  placeholder="Longer-form text content and notes"
                  value={formData.details}
                  onChange={(e) => setFormData({ ...formData, details: e.target.value })}
                  rows={4}
                  style={{
                    resize: 'vertical',
                    minHeight: '100px',
                  }}
                />
              </div>
              <div className="input-helper">Optional detailed information</div>
            </div>

            {/* Suggested Attributes */}
            {templateData && templateData.suggestedAttributes.length > 0 && (
              <>
                <div
                  style={{
                    borderTop: '1px solid var(--color-border)',
                    paddingTop: 'var(--spacing-4)',
                  }}
                >
                  <h3
                    style={{
                      fontFamily: 'var(--typography-heading-font)',
                      fontSize: 'var(--font-size-lg)',
                      fontWeight: 'var(--font-weight-semibold)',
                      color: 'var(--color-text-primary)',
                      margin: 0,
                      marginBottom: 'var(--spacing-3)',
                    }}
                  >
                    Attributes
                  </h3>
                  <p
                    style={{
                      fontFamily: 'var(--typography-body-font)',
                      fontSize: 'var(--font-size-sm)',
                      color: 'var(--color-text-secondary)',
                      margin: 0,
                      marginBottom: 'var(--spacing-4)',
                    }}
                  >
                    Edit attributes for this {templateData.name.toLowerCase()}.
                  </p>
                </div>

                <div
                  style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
                    gap: 'var(--spacing-4)',
                  }}
                >
                  {templateData.suggestedAttributes.map((attr) => (
                    <div key={attr.key} className="input-group input-5">
                      <label className="input-label" htmlFor={`attr-${attr.key}`}>
                        {attr.label}
                      </label>
                      <div className="input-wrapper">
                        <input
                          id={`attr-${attr.key}`}
                          type="text"
                          className="input-field input-base"
                          placeholder={attr.placeholder}
                          value={attributes[attr.key] || ''}
                          onChange={(e) => handleAttributeChange(attr.key, e.target.value)}
                        />
                      </div>
                      {attr.description && <div className="input-helper">{attr.description}</div>}
                    </div>
                  ))}
                </div>
              </>
            )}

            {/* Additional Options */}
            <div
              style={{
                borderTop: '1px solid var(--color-border)',
                paddingTop: 'var(--spacing-4)',
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
                gap: 'var(--spacing-4)',
              }}
            >
              {/* Tags */}
              <div className="input-group input-5">
                <label className="input-label" htmlFor="element-tags">
                  Tags
                </label>
                <div className="input-wrapper">
                  <input
                    id="element-tags"
                    type="text"
                    className="input-field input-base"
                    placeholder="hero, magic, warrior"
                    value={formData.tags}
                    onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
                  />
                </div>
                <div className="input-helper">Comma-separated tags</div>
              </div>

              {/* Color */}
              <div className="input-group input-5">
                <label className="input-label" htmlFor="element-color">
                  Color
                </label>
                <div className="input-wrapper">
                  <input
                    id="element-color"
                    type="text"
                    className="input-field input-base"
                    placeholder="#4F46E5"
                    value={formData.color}
                    onChange={(e) => setFormData({ ...formData, color: e.target.value })}
                  />
                </div>
                <div className="input-helper">Hex color code</div>
              </div>
            </div>
          </div>

          {/* Footer */}
          <div
            style={{
              display: 'flex',
              justifyContent: 'flex-end',
              gap: 'var(--spacing-3)',
              padding: 'var(--spacing-6)',
              borderTop: '1px solid var(--color-border)',
              backgroundColor: 'var(--color-background)',
            }}
          >
            <button
              type="button"
              className="btn btn-ghost btn-base"
              onClick={onClose}
              disabled={isSubmitting}
            >
              Cancel
            </button>
            <button type="submit" className="btn btn-primary btn-base" disabled={isSubmitting}>
              {isSubmitting ? 'Saving...' : 'Save Changes'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * StoryVersions View
 *
 * Displays and manages story versions using Database-Only Versioning (DBV).
 * Allows users to:
 * - List all versions for a story
 * - Create new versions (saves current snapshot first)
 * - Switch between versions
 * - Rename versions
 * - Delete versions (with warnings for active version, error for last version)
 */

import { ArrowLeft, Check, Pencil, Plus, StackSimple, Trash, Warning } from '@phosphor-icons/react';
import { useStoryVersions } from '@/features/stories/hooks/useStoryVersions';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';
import './StoryVersions.css';

export function StoryVersions() {
  const currentRoute = useNavigationStore((state) => state.currentRoute);
  const goBack = useNavigationStore((state) => state.goBack);

  // Extract storyId from route
  const storyId = currentRoute.screen === 'story-versions' ? currentRoute.storyId : '';

  const {
    story,
    versions,
    loading,
    error,
    showCreateForm,
    newVersionName,
    creating,
    createError,
    setShowCreateForm,
    setNewVersionName,
    handleCreateVersion,
    resetCreateForm,
    switching,
    handleSwitchVersion,
    editingVersionId,
    editingName,
    renaming,
    handleStartRename,
    handleSaveRename,
    handleCancelRename,
    setEditingName,
    deleteConfirm,
    deleting,
    deleteError,
    handleRequestDelete,
    handleConfirmDelete,
    handleCancelDelete,
  } = useStoryVersions(storyId);

  // Loading state
  if (loading) {
    return (
      <div className="story-versions-loading">
        <p>Loading versions...</p>
      </div>
    );
  }

  // Error state
  if (error && !story) {
    return (
      <div className="story-versions-error">
        <StackSimple size={48} />
        <h2>Error Loading Story</h2>
        <p>{error}</p>
        <button className="btn btn-primary btn-base" onClick={goBack}>
          Go Back
        </button>
      </div>
    );
  }

  return (
    <div className="story-versions">
      {/* Header */}
      <div className="story-versions-header">
        <button className="back-button" onClick={goBack} aria-label="Go back" title="Go back">
          <ArrowLeft size={20} />
        </button>
        <h1 className="page-title">Versions</h1>
      </div>

      {/* Content */}
      <div className="story-versions-content">
        {/* Story Info */}
        {story && (
          <div className="story-info">
            <h2>{story.title}</h2>
            <p className="story-subtitle">
              {versions.length} version{versions.length !== 1 ? 's' : ''}
            </p>
          </div>
        )}

        {/* Create Version Form */}
        {showCreateForm ? (
          <div className="create-version-form">
            <h3>Create New Version</h3>
            <form onSubmit={handleCreateVersion}>
              <div className="form-group">
                <label htmlFor="version-name">Version Name</label>
                <input
                  id="version-name"
                  type="text"
                  className="input input-filled"
                  value={newVersionName}
                  onChange={(e) => setNewVersionName(e.target.value)}
                  placeholder="e.g., Alternate Ending"
                  disabled={creating}
                  autoFocus
                />
                <p className="form-hint">
                  This will create a new version with a copy of your current content.
                </p>
                {createError && <p className="form-error">{createError}</p>}
              </div>
              <div className="form-actions">
                <button
                  type="submit"
                  className="btn btn-primary btn-base"
                  disabled={creating || !newVersionName.trim()}
                >
                  {creating ? 'Creating...' : 'Create Version'}
                </button>
                <button
                  type="button"
                  className="btn btn-ghost btn-base"
                  onClick={resetCreateForm}
                  disabled={creating}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        ) : (
          <button
            className="btn btn-primary btn-base create-version-button"
            onClick={() => setShowCreateForm(true)}
          >
            <Plus size={16} />
            New Version
          </button>
        )}

        {/* Versions List */}
        <div className="versions-section">
          <h3>All Versions</h3>
          {versions.length === 0 ? (
            <p className="empty-message">No versions found.</p>
          ) : (
            <div className="versions-list">
              {versions.map((version) => {
                const isActive = story?.activeVersionId === version.id;
                const isEditing = editingVersionId === version.id;
                const isSwitching = switching === version.id;

                return (
                  <div key={version.id} className={`version-item ${isActive ? 'current' : ''}`}>
                    <div className="version-info">
                      {isEditing ? (
                        <input
                          type="text"
                          className="input input-filled version-rename-input"
                          value={editingName}
                          onChange={(e) => setEditingName(e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') handleSaveRename();
                            if (e.key === 'Escape') handleCancelRename();
                          }}
                          disabled={renaming}
                          autoFocus
                        />
                      ) : (
                        <span className="version-name">{version.name}</span>
                      )}
                      {isActive && !isEditing && (
                        <span className="current-badge">
                          <Check size={12} weight="bold" />
                          Active
                        </span>
                      )}
                    </div>
                    <div className="version-actions">
                      {isEditing ? (
                        <>
                          <button
                            className="btn btn-primary btn-sm"
                            onClick={handleSaveRename}
                            disabled={renaming || !editingName.trim()}
                            title="Save"
                          >
                            {renaming ? 'Saving...' : 'Save'}
                          </button>
                          <button
                            className="btn btn-ghost btn-sm"
                            onClick={handleCancelRename}
                            disabled={renaming}
                            title="Cancel"
                          >
                            Cancel
                          </button>
                        </>
                      ) : (
                        <>
                          {!isActive && (
                            <button
                              className="btn btn-primary btn-sm"
                              onClick={() => handleSwitchVersion(version.id)}
                              disabled={!!switching}
                              title="Switch to this version"
                            >
                              {isSwitching ? 'Switching...' : 'Switch'}
                            </button>
                          )}
                          <button
                            className="btn btn-ghost btn-sm icon-btn"
                            onClick={() => handleStartRename(version)}
                            title="Rename version"
                            aria-label="Rename version"
                          >
                            <Pencil size={16} />
                          </button>
                          <button
                            className="btn btn-ghost btn-sm icon-btn delete-btn"
                            onClick={() => handleRequestDelete(version)}
                            title="Delete version"
                            aria-label="Delete version"
                          >
                            <Trash size={16} />
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      {deleteConfirm && (
        <div className="modal-overlay" onClick={handleCancelDelete}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              {deleteConfirm.isActive && <Warning size={24} className="warning-icon" />}
              <h3>Delete Version</h3>
            </div>
            <div className="modal-body">
              {deleteConfirm.isActive ? (
                <p>
                  <strong>"{deleteConfirm.versionName}"</strong> is your active version. Deleting it
                  will automatically switch to another version. Are you sure you want to continue?
                </p>
              ) : (
                <p>
                  Are you sure you want to delete version{' '}
                  <strong>"{deleteConfirm.versionName}"</strong>? This action cannot be undone.
                </p>
              )}
              {deleteError && <p className="form-error">{deleteError}</p>}
            </div>
            <div className="modal-actions">
              <button
                className="btn btn-ghost btn-base"
                onClick={handleCancelDelete}
                disabled={deleting}
              >
                Cancel
              </button>
              <button
                className="btn btn-danger btn-base"
                onClick={handleConfirmDelete}
                disabled={deleting}
              >
                {deleting ? 'Deleting...' : 'Delete'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Switching Overlay */}
      {switching && (
        <div className="switching-overlay">
          <p>Switching version...</p>
        </div>
      )}
    </div>
  );
}

