export function ConfirmDeleteModal({
  title,
  message,
  itemName,
  onConfirm,
  onCancel,
  isDeleting = false,
}: ConfirmDeleteModalProps) {
  const titleId = 'confirm-delete-modal-title';
  const messageId = 'confirm-delete-modal-message';
  const itemNameId = 'confirm-delete-modal-item';

  return (
    <div
      className="option-1 typo-1 icons-1 button-2"
      style={{
        position: 'fixed',
        inset: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
        zIndex: 1000,
      }}
      onClick={
        isDeleting
          ? undefined
          : (e) => {
              if (e.target === e.currentTarget) {
                onCancel();
              }
            }
      }
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
      aria-describedby={`${messageId} ${itemNameId}`}
    >
      <div
        style={{
          backgroundColor: 'var(--color-surface)',
          borderRadius: '8px',
          padding: 'var(--spacing-6)',
          maxWidth: '400px',
          width: '90%',
          boxShadow: 'var(--shadow-lg)',
        }}
      >

