/* biome-ignore lint/a11y/noAutofocus: approved text-entry autofocus for version creation */
<input
  id="version-name"
  type="text"
  className="input input-filled"
  value={newVersionName}
  onChange={(e) => setNewVersionName(e.target.value)}
  placeholder="e.g., Alternate Ending"
  disabled={creating}
  autoFocus
/>

/* biome-ignore lint/a11y/noAutofocus: approved text-entry autofocus for version renaming */
<input
  type="text"
  className="input input-filled version-rename-input"
  value={editingName}
  onChange={(e) => setEditingName(e.target.value)}
  onKeyDown={(e) => {
    if (e.key === 'Enter') handleSaveRename();
    if (e.key === 'Escape') handleCancelRename();
  }}
  disabled={renaming}
  autoFocus
/>

